'use strict';

// MODULES //

var contains = require( '@stdlib/array/base/assert/contains' ).factory;
var replace = require( '@stdlib/string/base/replace' );


// VARIABLES //

// Define a list of built-in Vega signal names that shouldn't be overwritten...
var EXCLUDE = [
	'width',
	'height',
	'padding',
	'autosize'
];
var isExcluded = contains( EXCLUDE );

var PREFIX = '_config_';
var RE_SLASH = /\//g;


// MAIN //

/**
* Returns an editor-specific signal name.
*
* ## Notes
*
* -   The intent of this function is to namespace editor signals to avoid potential naming collisions.
*
* @private
* @param {string} name - raw signal name
* @returns {string} signal name belonging to the editor signal namespace
*/
function signalName( name ) {
	if ( isExcluded( name ) ) {
		return name;
	}
	return PREFIX + replace( name, RE_SLASH, '_' );
}


// EXPORTS //

module.exports = signalName;
